// EncodeOrc writes the value to w in the Orc binary format.
func (s Source) EncodeOrc(w *orc.Writer) error {
	switch v := s.Variant.(type) {
	case ChannelSource:
		w.String("channel")
		if v.Key != nil {
			w.Bool(true)
			w.Uint32(uint32(*v.Key))
		} else {
			w.Bool(false)
		}
		if v.Command != nil {
			w.Bool(true)
			w.Uint32(uint32(*v.Command))
		} else {
			w.Bool(false)
		}
	case LocalSource:
		w.String("local")
		w.Float64(float64(v.Value))
	default:
		return errors.Newf("Source: nil or unknown variant %T", s.Variant)
	}
	return nil
}

// DecodeOrc reads the value from r in the Orc binary format.
func (s *Source) DecodeOrc(r *orc.Reader) error {
	tag, err := r.StringBytes()
	if err != nil {
		return err
	}
	switch string(tag) {
	case "channel":
		var v ChannelSource
		{
			present, err := r.Bool()
			if err != nil {
				return err
			}
			if present {
				var hv channel.Key
				{
					rawV, err := r.Uint32()
					if err != nil {
						return err
					}
					hv = channel.Key(rawV)
				}
				v.Key = &hv
			}
		}
		{
			present, err := r.Bool()
			if err != nil {
				return err
			}
			if present {
				var hv channel.Key
				{
					rawV, err := r.Uint32()
					if err != nil {
						return err
					}
					hv = channel.Key(rawV)
				}
				v.Command = &hv
			}
		}
		s.Variant = v
	case "local":
		var v LocalSource
		if v.Value, err = r.Float64(); err != nil {
			return err
		}
		s.Variant = v
	default:
		return errors.Newf("Source: unknown variant %q", tag)
	}
	return nil
}

